def crear_perfiles_existentes(apps, schema_editor):
    Usuario = apps.get_model('auth', 'User')
    Perfil = apps.get_model('api', 'PerfilUsuario')
    for usuario in Usuario.objects.all():
        rol = 'EJECUTIVO_ARRIENDOS' if usuario.is_staff else 'EMPRESA_CONSTRUCTORA'
        Perfil.objects.get_or_create(usuario=usuario, defaults={'rol': rol})


